%[text] hold on;
%[text] plot(x_vct, Q_pts(:, 1), 'b-', 'LineWidth', 2);
%[text] plot(x_vct, Q_pts(:, 2), 'b-.', 'LineWidth', 2);
%[text] plot(x_vct, Q_pts(:, 3), 'r-', 'LineWidth', 2);
%[text] plot(x_vct, Q_pts(:, 4), 'r-.', 'LineWidth', 2);
%[text] plot(x_vct, Q_pts(:, 5), 'm-', 'LineWidth', 2);
%[text] plot(x_vct, Q_pts(:, 6), 'k-', 'LineWidth', 2);
%[text] legend("", "L1", "L1_{RI}", "L2", "L2_{RI}", "E/B", "analytical")
%[text] hold off;
%[text] xlabel("$X$", Interpreter="latex")
%[text] ylabel("$Q$", Interpreter="latex")
%[text] title("Shear forces $Q$ along the beam", Interpreter="latex")
%[text] ```
